inline a_boolean is_supported_ifc_version(an_ifc_version major_version,
                                          an_ifc_version minor_version)
/*
Given a major and minor IFC version number, return TRUE if the version is
supported, otherwise return FALSE.
*/
{
  a_boolean result = FALSE;

  switch (major_version) {
    case 0:
      switch (minor_version) {
        case 41:
        case 33:
          result = TRUE;
          break;
        default:
          break;
      }  /* switch */
      break;
    default:
      break;
  }  /* switch */
  return result;
}  /* is_supported_ifc_version */


/*
Functions for interacting with IFC AccessSort sorts.
*/


inline a_const_char* str_for(an_ifc_access_sort universal)
/*
Given the universal representation of AccessSort, return the the textual name
in the form a c-string.
*/
{
  a_const_char *result;

  switch (universal) {
    case ifc_as_none:
      result = "AccessSort::None";
      break;
    case ifc_as_private:
      result = "AccessSort::Private";
      break;
    case ifc_as_protected:
      result = "AccessSort::Protected";
      break;
    case ifc_as_public:
      result = "AccessSort::Public";
      break;
    default:
      unexpected_condition_str("Invalid value for a AccessSort.");
      break;
  }  /* switch */
  return result;
}  /* str_for */


inline an_ifc_encoded_access_sort to_encoded(an_ifc_module      *mod,
                                             an_ifc_access_sort universal)
/*
Given the universal representation of AccessSort and the destination module,
return a reencoded sort value.
*/
{
  using ue_ty = an_ifc_encoded_access_sort_storage;
  an_ifc_encoded_access_sort_storage result;

  switch (universal) {
    case ifc_as_none:
      result = (ue_ty)ifc_0_33_as_none;
      break;
    case ifc_as_private:
      result = (ue_ty)ifc_0_33_as_private;
      break;
    case ifc_as_protected:
      result = (ue_ty)ifc_0_33_as_protected;
      break;
    case ifc_as_public:
      result = (ue_ty)ifc_0_33_as_public;
      break;
    default:
      unexpected_condition_str("Invalid value for a AccessSort.");
      break;
  }  /* switch */
  return an_ifc_encoded_access_sort{mod, result};
}  /* to_encoded */


inline a_boolean validate_sort(an_ifc_access_sort_0_33       versioned,
                               const an_ifc_validation_trace *parent)
/*
Given the versioned representation of AccessSort, return TRUE if the value
represents a valid enumerator; otherwise, return FALSE.
*/
{
  a_boolean result = FALSE;

  switch (versioned) {
    case ifc_0_33_as_none:
    case ifc_0_33_as_private:
    case ifc_0_33_as_protected:
    case ifc_0_33_as_public:
      result = TRUE;
      break;
    default:
      break;
  }  /* switch */
  return result;
}  /* validate_sort */


