inline an_ifc_keyword_sort get_ifc_value(
                                an_ifc_module                       *mod,
                                const an_ifc_keyword_syntax_storage *universal)
/*
Given the universal storage representation of KeywordSyntax and the associated
module, return the universal representation of the field "value".
*/
{
  an_ifc_keyword_sort result;

  /* Ensure the value field exists in the current module version. */
  check_assertion(has_ifc_value(mod, universal));
  an_ifc_keyword_sort_0_33 stage_0;
  an_ifc_keyword_sort      stage_1;

  /* Copy the field (KeywordSyntax::value - KeywordSort) into version specific
     storage. */
  static_assert(sizeof(stage_0) == 4,
                "stage_0 is not properly sized storage!");
  copy_ifc_field(&stage_0, universal, /*offset=*/8);
  stage_1 = to_universal_sort(stage_0);
  result = stage_1;
  return result;
}  /* get_ifc_value */


