inline a_boolean validate(an_ifc_module                       *mod,
                          const an_ifc_keyword_syntax_storage *universal,
                          const an_ifc_validation_trace       *parent)
/*
Given the universal storage representation of KeywordSyntax and the associated
module, return TRUE if the representation is valid; otherwise, return FALSE.
*/
{
  a_boolean result = TRUE;

  if (has_ifc_locus(mod, universal)) {
    an_ifc_source_location_bytes stage_0;
    an_ifc_validation_trace      stage_0_trace =
                                               {"locus", /*offset=*/0, parent};
    an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (KeywordSyntax::locus - SourceLocation). */
    stage_0 = (an_ifc_source_location_bytes)((*universal) + 0);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (KeywordSyntax::locus - SourceLocation) into universal
       storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/0, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_value(mod, universal)) {
    an_ifc_keyword_sort_0_33 stage_0;
    an_ifc_validation_trace  stage_0_trace = {"value", /*offset=*/8, parent};

    /* Copy the field (KeywordSyntax::value - KeywordSort) into version
       specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/8);
    if (!validate_sort(stage_0, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
done:
  return result;
}  /* validate */


inline a_boolean validate(const an_ifc_keyword_syntax   &universal,
                          const an_ifc_validation_trace *parent)
/*
Given the universal representation of KeywordSyntax, return TRUE if the
representation is valid; otherwise, return FALSE.
*/
{
  return validate(universal.get_module(), universal.get_storage(), parent);
}  /* validate */


#if DEBUG
void db_node(an_ifc_module                       *mod,
             const an_ifc_keyword_syntax_storage *universal,
             unsigned                            indent)
/*
Given the universal representation of KeywordSyntax, print a diagnostic textual
representation with the given indent.
*/
{
  if (has_ifc_locus(mod, universal)) {
    an_ifc_source_location field = get_ifc_locus(mod, universal);

    for (unsigned i = 0; i < indent; ++i) {
      fprintf(f_debug, "  ");
    }  /* for */
    fprintf(f_debug, "locus:\n");
    db_node(field.get_module(), field.get_storage(), indent + 1);
  }  /* if */
  if (has_ifc_value(mod, universal)) {
    an_ifc_keyword_sort field = get_ifc_value(mod, universal);

    for (unsigned i = 0; i < indent; ++i) {
      fprintf(f_debug, "  ");
    }  /* for */
    fprintf(f_debug, "value: %s\n", str_for(field));
  }  /* if */
}  /* db_node */


void db_node(const an_ifc_keyword_syntax &universal)
/*
Given the universal representation of KeywordSyntax, print a diagnostic textual
representation.
*/
{
  db_node(universal.get_module(), universal.get_storage(), 0);
}  /* db_node */
#endif /* DEBUG */


