inline a_boolean validate(an_ifc_module                    *mod,
                          const an_ifc_file_header_storage *universal,
                          const an_ifc_validation_trace    *parent)
/*
Given the universal storage representation of FileHeader and the associated
module, return TRUE if the representation is valid; otherwise, return FALSE.
*/
{
  a_boolean result = TRUE;

  if (has_ifc_arch(mod, universal)) {
    an_ifc_architecture_sort_0_33 stage_0;
    an_ifc_validation_trace       stage_0_trace =
                                               {"arch", /*offset=*/35, parent};

    /* Copy the field (FileHeader::arch - ArchitectureSort) into version
       specific storage. */
    static_assert(sizeof(stage_0) == 1,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/35);
    if (!validate_sort(stage_0, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_unit(mod, universal)) {
    an_ifc_unit_index_0_33  stage_0;
    an_ifc_validation_trace stage_0_trace = {"unit", /*offset=*/48, parent};

    /* Copy the field (FileHeader::unit - UnitIndex) into version specific
       storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/48);
    if (!validate_index(mod, stage_0, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
done:
  return result;
}  /* validate */


inline a_boolean validate(const an_ifc_file_header      &universal,
                          const an_ifc_validation_trace *parent)
/*
Given the universal representation of FileHeader, return TRUE if the
representation is valid; otherwise, return FALSE.
*/
{
  return validate(universal.get_module(), universal.get_storage(), parent);
}  /* validate */


