inline a_boolean has_ifc_cardinality(an_ifc_module                  *mod,
                                     const an_ifc_partition_storage *universal)
/*
Return TRUE if the given universal representation storage from the given module
has the field "cardinality"; otherwise, return FALSE.
*/
{
  a_boolean result = get_fallback_presence_value(mod);

  if (is_at_least(mod, 0, 33)) {
    result = TRUE;
  }  /* if */
  return result;
}  /* has_ifc_cardinality */


inline a_boolean has_ifc_cardinality(const an_ifc_partition &universal)
/*
Return TRUE if the given universal representation has the field "cardinality";
otherwise, return FALSE.
*/
{
  return has_ifc_cardinality(universal.get_module(), universal.get_storage());
}  /* has_ifc_cardinality */


inline an_ifc_cardinality get_ifc_cardinality(
                                     an_ifc_module                  *mod,
                                     const an_ifc_partition_storage *universal)
/*
Given the universal storage representation of Partition and the associated
module, return the universal representation of the field "cardinality".
*/
{
  an_ifc_cardinality result;

  /* Ensure the cardinality field exists in the current module version. */
  check_assertion(has_ifc_cardinality(mod, universal));
  /* Copy the contents to an appropriately sized variable.  Then, copy via
     language rules into a (possibly wider) native type.  This is irrelevant
     (and should be optimized away) on little-endian architectures.  However,
     when running on big-endian architectures this process ensures the value
     isn't mangled (as with high order bits first, a wider integer increases
     the value if the bits aren't positioned properly). */
  an_ifc_cardinality_0_33 stage_0;
  an_ifc_cardinality      stage_1;

  /* Copy the field (Partition::cardinality - Cardinality) into version
     specific storage. */
  static_assert(sizeof(stage_0) == 4,
                "stage_0 is not properly sized storage!");
  copy_ifc_field(&stage_0, universal, /*offset=*/8);
  stage_1 = {mod, (an_ifc_cardinality_storage)stage_0};
  result = stage_1;
  return result;
}  /* get_ifc_cardinality */


