inline an_ifc_nestable_word get_ifc_word(
                                    an_ifc_module                   *mod,
                                    const an_ifc_attr_basic_storage *universal)
/*
Given the universal storage representation of AttrBasic and the associated
module, return the universal representation of the field "word".
*/
{
  an_ifc_nestable_word result;

  /* Ensure the word field exists in the current module version. */
  check_assertion(has_ifc_word(mod, universal));
  an_ifc_nestable_word_bytes stage_0;
  an_ifc_nestable_word       stage_1;

#if USE_MMAP_FOR_MODULES
  /* Update the universal storage pointer to the start of the field
     (AttrBasic::word - NestableWord). */
  stage_0 = (an_ifc_nestable_word_bytes)((*universal) + 0);
#else /* !USE_MMAP_FOR_MODULES */
  /* Copy the field (AttrBasic::word - NestableWord) into universal storage. */
  copy_ifc_field(&stage_0, universal, /*offset=*/0, /*size=*/16);
#endif /* USE_MMAP_FOR_MODULES */
  stage_1 = {mod, stage_0};
  result = stage_1;
  return result;
}  /* get_ifc_word */


