inline a_boolean validate(an_ifc_module                    *mod,
                          const an_ifc_attr_scoped_storage *universal,
                          const an_ifc_validation_trace    *parent)
/*
Given the universal storage representation of AttrScoped and the associated
module, return TRUE if the representation is valid; otherwise, return FALSE.
*/
{
  a_boolean result = TRUE;

  if (has_ifc_member(mod, universal)) {
    an_ifc_nestable_word_bytes stage_0;
    an_ifc_validation_trace    stage_0_trace =
                                             {"member", /*offset=*/16, parent};
    an_ifc_nestable_word       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (AttrScoped::member - NestableWord). */
    stage_0 = (an_ifc_nestable_word_bytes)((*universal) + 16);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (AttrScoped::member - NestableWord) into universal
       storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/16, /*size=*/16);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_scope(mod, universal)) {
    an_ifc_nestable_word_bytes stage_0;
    an_ifc_validation_trace    stage_0_trace = {"scope", /*offset=*/0, parent};
    an_ifc_nestable_word       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (AttrScoped::scope - NestableWord). */
    stage_0 = (an_ifc_nestable_word_bytes)((*universal) + 0);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (AttrScoped::scope - NestableWord) into universal
       storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/0, /*size=*/16);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
done:
  return result;
}  /* validate */


inline a_boolean validate(const an_ifc_attr_scoped      &universal,
                          const an_ifc_validation_trace *parent)
/*
Given the universal representation of AttrScoped, return TRUE if the
representation is valid; otherwise, return FALSE.
*/
{
  return validate(universal.get_module(), universal.get_storage(), parent);
}  /* validate */


