inline a_boolean validate(an_ifc_module                       *mod,
                          const an_ifc_chart_unilevel_storage *universal,
                          const an_ifc_validation_trace       *parent)
/*
Given the universal storage representation of ChartUnilevel and the associated
module, return TRUE if the representation is valid; otherwise, return FALSE.
*/
{
  a_boolean result = TRUE;

  if (has_ifc_constraint(mod, universal)) {
    an_ifc_expr_index_0_33  stage_0;
    an_ifc_validation_trace stage_0_trace =
                                          {"constraint", /*offset=*/8, parent};

    /* Copy the field (ChartUnilevel::constraint - ExprIndex) into version
       specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/8);
    if (!validate_index(mod, stage_0, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
done:
  return result;
}  /* validate */


