inline a_boolean has_ifc_access(an_ifc_module                     *mod,
                                const an_ifc_decl_concept_storage *universal)
/*
Return TRUE if the given universal representation storage from the given module
has the field "access"; otherwise, return FALSE.
*/
{
  a_boolean result = get_fallback_presence_value(mod);

  if (is_at_least(mod, 0, 33)) {
    result = TRUE;
  }  /* if */
  return result;
}  /* has_ifc_access */


inline a_boolean has_ifc_access(const an_ifc_decl_concept &universal)
/*
Return TRUE if the given universal representation has the field "access";
otherwise, return FALSE.
*/
{
  return has_ifc_access(universal.get_module(), universal.get_storage());
}  /* has_ifc_access */


inline an_ifc_access_sort get_ifc_access(
                                  an_ifc_module                     *mod,
                                  const an_ifc_decl_concept_storage *universal)
/*
Given the universal storage representation of DeclConcept and the associated
module, return the universal representation of the field "access".
*/
{
  an_ifc_access_sort result;

  /* Ensure the access field exists in the current module version. */
  check_assertion(has_ifc_access(mod, universal));
  an_ifc_access_sort_0_33 stage_0;
  an_ifc_access_sort      stage_1;

  /* Copy the field (DeclConcept::access - AccessSort) into version specific
     storage. */
  static_assert(sizeof(stage_0) == 1,
                "stage_0 is not properly sized storage!");
  copy_ifc_field(&stage_0, universal, /*offset=*/29);
  stage_1 = to_universal_sort(stage_0);
  result = stage_1;
  return result;
}  /* get_ifc_access */


