inline an_ifc_access_sort get_ifc_access(
                              an_ifc_module                         *mod,
                              const an_ifc_decl_constructor_storage *universal)
/*
Given the universal storage representation of DeclConstructor and the
associated module, return the universal representation of the field "access".
*/
{
  an_ifc_access_sort result;

  /* Ensure the access field exists in the current module version. */
  check_assertion(has_ifc_access(mod, universal));
  an_ifc_access_sort_0_33 stage_0;
  an_ifc_access_sort      stage_1;

  /* Copy the field (DeclConstructor::access - AccessSort) into version
     specific storage. */
  static_assert(sizeof(stage_0) == 1,
                "stage_0 is not properly sized storage!");
  copy_ifc_field(&stage_0, universal, /*offset=*/27);
  stage_1 = to_universal_sort(stage_0);
  result = stage_1;
  return result;
}  /* get_ifc_access */


