inline an_ifc_decl_index get_ifc_home_scope(
                              an_ifc_module                         *mod,
                              const an_ifc_decl_enumeration_storage *universal)
/*
Given the universal storage representation of DeclEnumeration and the
associated module, return the universal representation of the field
"home_scope".
*/
{
  an_ifc_decl_index result;

  /* Ensure the home_scope field exists in the current module version. */
  check_assertion(has_ifc_home_scope(mod, universal));
  if (is_at_least(mod, 0, 41)) {
    an_ifc_decl_index_0_41 stage_0;
    an_ifc_decl_index      stage_1;
    a_boolean              stage_2;
    an_ifc_decl_index      stage_3;

    /* Copy the field (DeclEnumeration::home_scope - DeclIndex) into version
       specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/28);
    stage_1 = to_universal_index(mod, stage_0);
    if (stage_1.sort == ifc_ds_decl_specialization) {
      stage_2 = TRUE;
    } else {
      stage_2 = FALSE;
    }  /* if */
    if (stage_2) {
      an_ifc_decl_index_0_41     stage_3_0;
      an_ifc_decl_index          stage_3_1;
      an_ifc_decl_specialization stage_3_2;
      an_ifc_decl_index_0_41     stage_3_3;
      an_ifc_decl_index          stage_3_4;

      /* Copy the field (DeclEnumeration::home_scope - DeclIndex) into version
         specific storage. */
      static_assert(sizeof(stage_3_0) == 4,
                    "stage_3_0 is not properly sized storage!");
      copy_ifc_field(&stage_3_0, universal, /*offset=*/28);
      stage_3_1 = to_universal_index(mod, stage_3_0);
      /* Use the obtained index to retrieve the appropriate instance of
         DeclSpecialization (the type tag should have been prechecked by
         validation).  Then, retrieve and return the desired value held by the
         field decl. */
      construct_node_unchecked(&stage_3_2, stage_3_1);
      /* Copy the field (DeclSpecialization::decl - DeclIndex) into version
         specific storage. */
      static_assert(sizeof(stage_3_3) == 4,
                    "stage_3_3 is not properly sized storage!");
      copy_ifc_field(&stage_3_3, stage_3_2.get_storage(), /*offset=*/4);
      stage_3_4 = to_universal_index(mod, stage_3_3);
      stage_3 = stage_3_4;
    } else {
      an_ifc_decl_index_0_41 stage_3_0;
      an_ifc_decl_index      stage_3_1;

      /* Copy the field (DeclEnumeration::home_scope - DeclIndex) into version
         specific storage. */
      static_assert(sizeof(stage_3_0) == 4,
                    "stage_3_0 is not properly sized storage!");
      copy_ifc_field(&stage_3_0, universal, /*offset=*/28);
      stage_3_1 = to_universal_index(mod, stage_3_0);
      stage_3 = stage_3_1;
    }  /* if */
    result = stage_3;
  } else {
    an_ifc_decl_index_0_33 stage_0;
    an_ifc_decl_index      stage_1;

    /* Copy the field (DeclEnumeration::home_scope - DeclIndex) into version
       specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/28);
    stage_1 = to_universal_index(mod, stage_0);
    result = stage_1;
  }  /* if */
  return result;
}  /* get_ifc_home_scope */


