inline an_ifc_decl_index get_ifc_operand(
                                an_ifc_module                       *mod,
                                const an_ifc_decl_expansion_storage *universal)
/*
Given the universal storage representation of DeclExpansion and the associated
module, return the universal representation of the field "operand".
*/
{
  an_ifc_decl_index result;

  /* Ensure the operand field exists in the current module version. */
  check_assertion(has_ifc_operand(mod, universal));
  if (is_at_least(mod, 0, 41)) {
    an_ifc_decl_index_0_41 stage_0;
    an_ifc_decl_index      stage_1;

    /* Copy the field (DeclExpansion::operand - DeclIndex) into version
       specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/0);
    stage_1 = to_universal_index(mod, stage_0);
    result = stage_1;
  } else {
    an_ifc_decl_index_0_33 stage_0;
    an_ifc_decl_index      stage_1;

    /* Copy the field (DeclExpansion::operand - DeclIndex) into version
       specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/0);
    stage_1 = to_universal_index(mod, stage_0);
    result = stage_1;
  }  /* if */
  return result;
}  /* get_ifc_operand */


