inline a_boolean validate(an_ifc_module                       *mod,
                          const an_ifc_decl_expansion_storage *universal,
                          const an_ifc_validation_trace       *parent)
/*
Given the universal storage representation of DeclExpansion and the associated
module, return TRUE if the representation is valid; otherwise, return FALSE.
*/
{
  a_boolean result = TRUE;

  if (has_ifc_locus(mod, universal)) {
    an_ifc_source_location_bytes stage_0;
    an_ifc_validation_trace      stage_0_trace =
                                               {"locus", /*offset=*/4, parent};
    an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (DeclExpansion::locus - SourceLocation). */
    stage_0 = (an_ifc_source_location_bytes)((*universal) + 4);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (DeclExpansion::locus - SourceLocation) into universal
       storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/4, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_operand(mod, universal)) {
    if (is_at_least(mod, 0, 41)) {
      an_ifc_decl_index_0_41  stage_0;
      an_ifc_validation_trace stage_0_trace =
                                             {"operand", /*offset=*/0, parent};

      /* Copy the field (DeclExpansion::operand - DeclIndex) into version
         specific storage. */
      static_assert(sizeof(stage_0) == 4,
                    "stage_0 is not properly sized storage!");
      copy_ifc_field(&stage_0, universal, /*offset=*/0);
      if (!validate_index(mod, stage_0, &stage_0_trace)) {
        result = FALSE;
        goto done;
      }  /* if */
    } else {
      an_ifc_decl_index_0_33  stage_0;
      an_ifc_validation_trace stage_0_trace =
                                             {"operand", /*offset=*/0, parent};

      /* Copy the field (DeclExpansion::operand - DeclIndex) into version
         specific storage. */
      static_assert(sizeof(stage_0) == 4,
                    "stage_0 is not properly sized storage!");
      copy_ifc_field(&stage_0, universal, /*offset=*/0);
      if (!validate_index(mod, stage_0, &stage_0_trace)) {
        result = FALSE;
        goto done;
      }  /* if */
    }  /* if */
  }  /* if */
done:
  return result;
}  /* validate */


inline a_boolean validate(const an_ifc_decl_expansion   &universal,
                          const an_ifc_validation_trace *parent)
/*
Given the universal representation of DeclExpansion, return TRUE if the
representation is valid; otherwise, return FALSE.
*/
{
  return validate(universal.get_module(), universal.get_storage(), parent);
}  /* validate */


