inline a_boolean has_ifc_index(an_ifc_module                       *mod,
                               const an_ifc_decl_reference_storage *universal)
/*
Return TRUE if the given universal representation storage from the given module
has the field "index"; otherwise, return FALSE.
*/
{
  a_boolean result = get_fallback_presence_value(mod);

  if (is_at_least(mod, 0, 33)) {
    result = TRUE;
  }  /* if */
  return result;
}  /* has_ifc_index */


inline a_boolean has_ifc_index(const an_ifc_decl_reference &universal)
/*
Return TRUE if the given universal representation has the field "index";
otherwise, return FALSE.
*/
{
  return has_ifc_index(universal.get_module(), universal.get_storage());
}  /* has_ifc_index */


inline an_ifc_decl_index get_ifc_index(
                                an_ifc_module                       *mod,
                                const an_ifc_decl_reference_storage *universal)
/*
Given the universal storage representation of DeclReference and the associated
module, return the universal representation of the field "index".
*/
{
  an_ifc_decl_index result;

  /* Ensure the index field exists in the current module version. */
  check_assertion(has_ifc_index(mod, universal));
  an_ifc_module_reference_bytes  stage_0;
  an_ifc_module_reference        stage_1;
  an_ifc_module                  *stage_2;
  an_ifc_decl_foreign_index_0_33 stage_3;
  an_ifc_decl_foreign_index      stage_4;
  an_ifc_decl_index              stage_5;

#if USE_MMAP_FOR_MODULES
  /* Update the universal storage pointer to the start of the field
     (DeclReference::unit - ModuleReference). */
  stage_0 = (an_ifc_module_reference_bytes)((*universal) + 0);
#else /* !USE_MMAP_FOR_MODULES */
  /* Copy the field (DeclReference::unit - ModuleReference) into universal
     storage. */
  copy_ifc_field(&stage_0, universal, /*offset=*/0, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
  stage_1 = {mod, stage_0};
  stage_2 = get_module(stage_1);
  /* Copy the field (DeclReference::local_index - DeclForeignIndex) into
     version specific storage. */
  static_assert(sizeof(stage_3) == 4,
                "stage_3 is not properly sized storage!");
  copy_ifc_field(&stage_3, universal, /*offset=*/8);
  stage_4 = {mod, (an_ifc_decl_foreign_index_storage)stage_3};
  stage_5 = to_universal_index(stage_2, stage_4);
  result = stage_5;
  return result;
}  /* get_ifc_index */


inline an_ifc_decl_index get_ifc_index(const an_ifc_decl_reference &universal)
/*
Given the universal representation of DeclReference, return the universal
representation of the field "index".
*/
{
  return get_ifc_index(universal.get_module(), universal.get_storage());
}  /* get_ifc_index */


