inline an_ifc_decl_foreign_index get_ifc_local_index(
                                an_ifc_module                       *mod,
                                const an_ifc_decl_reference_storage *universal)
/*
Given the universal storage representation of DeclReference and the associated
module, return the universal representation of the field "local_index".
*/
{
  an_ifc_decl_foreign_index result;

  /* Ensure the local_index field exists in the current module version. */
  check_assertion(has_ifc_local_index(mod, universal));
  /* Copy the contents to an appropriately sized variable.  Then, copy via
     language rules into a (possibly wider) native type.  This is irrelevant
     (and should be optimized away) on little-endian architectures.  However,
     when running on big-endian architectures this process ensures the value
     isn't mangled (as with high order bits first, a wider integer increases
     the value if the bits aren't positioned properly). */
  an_ifc_decl_foreign_index_0_33 stage_0;
  an_ifc_decl_foreign_index      stage_1;

  /* Copy the field (DeclReference::local_index - DeclForeignIndex) into
     version specific storage. */
  static_assert(sizeof(stage_0) == 4,
                "stage_0 is not properly sized storage!");
  copy_ifc_field(&stage_0, universal, /*offset=*/8);
  stage_1 = {mod, (an_ifc_decl_foreign_index_storage)stage_0};
  result = stage_1;
  return result;
}  /* get_ifc_local_index */


