inline a_boolean has_ifc_decl(
                           an_ifc_module                            *mod,
                           const an_ifc_decl_specialization_storage *universal)
/*
Return TRUE if the given universal representation storage from the given module
has the field "decl"; otherwise, return FALSE.
*/
{
  a_boolean result = get_fallback_presence_value(mod);

  if (is_at_least(mod, 0, 41)) {
    result = TRUE;
  }  /* if */
  return result;
}  /* has_ifc_decl */


inline a_boolean has_ifc_decl(const an_ifc_decl_specialization &universal)
/*
Return TRUE if the given universal representation has the field "decl";
otherwise, return FALSE.
*/
{
  return has_ifc_decl(universal.get_module(), universal.get_storage());
}  /* has_ifc_decl */


inline an_ifc_decl_index get_ifc_decl(
                           an_ifc_module                            *mod,
                           const an_ifc_decl_specialization_storage *universal)
/*
Given the universal storage representation of DeclSpecialization and the
associated module, return the universal representation of the field "decl".
*/
{
  an_ifc_decl_index result;

  /* Ensure the decl field exists in the current module version. */
  check_assertion(has_ifc_decl(mod, universal));
  an_ifc_decl_index_0_41 stage_0;
  an_ifc_decl_index      stage_1;

  /* Copy the field (DeclSpecialization::decl - DeclIndex) into version
     specific storage. */
  static_assert(sizeof(stage_0) == 4,
                "stage_0 is not properly sized storage!");
  copy_ifc_field(&stage_0, universal, /*offset=*/4);
  stage_1 = to_universal_index(mod, stage_0);
  result = stage_1;
  return result;
}  /* get_ifc_decl */


inline an_ifc_decl_index get_ifc_decl(
                                   const an_ifc_decl_specialization &universal)
/*
Given the universal representation of DeclSpecialization, return the universal
representation of the field "decl".
*/
{
  return get_ifc_decl(universal.get_module(), universal.get_storage());
}  /* get_ifc_decl */


