inline a_boolean has_ifc_chart(an_ifc_module                      *mod,
                               const an_ifc_decl_temploid_storage *universal)
/*
Return TRUE if the given universal representation storage from the given module
has the field "chart"; otherwise, return FALSE.
*/
{
  a_boolean result = get_fallback_presence_value(mod);

  if (is_at_least(mod, 0, 33)) {
    result = TRUE;
  }  /* if */
  return result;
}  /* has_ifc_chart */


inline a_boolean has_ifc_chart(const an_ifc_decl_temploid &universal)
/*
Return TRUE if the given universal representation has the field "chart";
otherwise, return FALSE.
*/
{
  return has_ifc_chart(universal.get_module(), universal.get_storage());
}  /* has_ifc_chart */


inline an_ifc_chart_index get_ifc_chart(
                                 an_ifc_module                      *mod,
                                 const an_ifc_decl_temploid_storage *universal)
/*
Given the universal storage representation of DeclTemploid and the associated
module, return the universal representation of the field "chart".
*/
{
  an_ifc_chart_index result;

  /* Ensure the chart field exists in the current module version. */
  check_assertion(has_ifc_chart(mod, universal));
  an_ifc_chart_index_0_33 stage_0;
  an_ifc_chart_index      stage_1;

  /* Copy the field (DeclTemploid::chart - ChartIndex) into version specific
     storage. */
  static_assert(sizeof(stage_0) == 4,
                "stage_0 is not properly sized storage!");
  copy_ifc_field(&stage_0, universal, /*offset=*/16);
  stage_1 = to_universal_index(mod, stage_0);
  result = stage_1;
  return result;
}  /* get_ifc_chart */


inline an_ifc_chart_index get_ifc_chart(const an_ifc_decl_temploid &universal)
/*
Given the universal representation of DeclTemploid, return the universal
representation of the field "chart".
*/
{
  return get_ifc_chart(universal.get_module(), universal.get_storage());
}  /* get_ifc_chart */


