inline a_boolean validate(an_ifc_module                    *mod,
                          const an_ifc_expr_lambda_storage *universal,
                          const an_ifc_validation_trace    *parent)
/*
Given the universal storage representation of ExprLambda and the associated
module, return TRUE if the representation is valid; otherwise, return FALSE.
*/
{
  a_boolean result = TRUE;

  if (has_ifc_body(mod, universal)) {
    an_ifc_syntax_index_0_33 stage_0;
    an_ifc_validation_trace  stage_0_trace = {"body", /*offset=*/16, parent};

    /* Copy the field (ExprLambda::body - SyntaxIndex) into version specific
       storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/16);
    if (!validate_index(mod, stage_0, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_constraint(mod, universal)) {
    an_ifc_syntax_index_0_33 stage_0;
    an_ifc_validation_trace  stage_0_trace =
                                         {"constraint", /*offset=*/12, parent};

    /* Copy the field (ExprLambda::constraint - SyntaxIndex) into version
       specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/12);
    if (!validate_index(mod, stage_0, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_declarator(mod, universal)) {
    an_ifc_syntax_index_0_33 stage_0;
    an_ifc_validation_trace  stage_0_trace =
                                          {"declarator", /*offset=*/8, parent};

    /* Copy the field (ExprLambda::declarator - SyntaxIndex) into version
       specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/8);
    if (!validate_index(mod, stage_0, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_introducer(mod, universal)) {
    an_ifc_syntax_index_0_33 stage_0;
    an_ifc_validation_trace  stage_0_trace =
                                          {"introducer", /*offset=*/0, parent};

    /* Copy the field (ExprLambda::introducer - SyntaxIndex) into version
       specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/0);
    if (!validate_index(mod, stage_0, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_template_parameters(mod, universal)) {
    an_ifc_syntax_index_0_33 stage_0;
    an_ifc_validation_trace  stage_0_trace =
                                 {"template_parameters", /*offset=*/4, parent};

    /* Copy the field (ExprLambda::template_parameters - SyntaxIndex) into
       version specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/4);
    if (!validate_index(mod, stage_0, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
done:
  return result;
}  /* validate */


inline a_boolean validate(const an_ifc_expr_lambda      &universal,
                          const an_ifc_validation_trace *parent)
/*
Given the universal representation of ExprLambda, return TRUE if the
representation is valid; otherwise, return FALSE.
*/
{
  return validate(universal.get_module(), universal.get_storage(), parent);
}  /* validate */


