inline a_boolean has_ifc_body(an_ifc_module                      *mod,
                              const an_ifc_expr_requires_storage *universal)
/*
Return TRUE if the given universal representation storage from the given module
has the field "body"; otherwise, return FALSE.
*/
{
  a_boolean result = get_fallback_presence_value(mod);

  if (is_at_least(mod, 0, 33)) {
    result = TRUE;
  }  /* if */
  return result;
}  /* has_ifc_body */


inline a_boolean has_ifc_body(const an_ifc_expr_requires &universal)
/*
Return TRUE if the given universal representation has the field "body";
otherwise, return FALSE.
*/
{
  return has_ifc_body(universal.get_module(), universal.get_storage());
}  /* has_ifc_body */


inline an_ifc_syntax_index get_ifc_body(
                                 an_ifc_module                      *mod,
                                 const an_ifc_expr_requires_storage *universal)
/*
Given the universal storage representation of ExprRequires and the associated
module, return the universal representation of the field "body".
*/
{
  an_ifc_syntax_index result;

  /* Ensure the body field exists in the current module version. */
  check_assertion(has_ifc_body(mod, universal));
  an_ifc_syntax_index_0_33 stage_0;
  an_ifc_syntax_index      stage_1;

  /* Copy the field (ExprRequires::body - SyntaxIndex) into version specific
     storage. */
  static_assert(sizeof(stage_0) == 4,
                "stage_0 is not properly sized storage!");
  copy_ifc_field(&stage_0, universal, /*offset=*/16);
  stage_1 = to_universal_index(mod, stage_0);
  result = stage_1;
  return result;
}  /* get_ifc_body */


