inline a_boolean has_ifc_function(
              an_ifc_module                                         *mod,
              const an_ifc_expr_virtual_function_conversion_storage *universal)
/*
Return TRUE if the given universal representation storage from the given module
has the field "function"; otherwise, return FALSE.
*/
{
  a_boolean result = get_fallback_presence_value(mod);

  if (is_at_least(mod, 0, 33)) {
    result = TRUE;
  }  /* if */
  return result;
}  /* has_ifc_function */


