inline a_boolean has_ifc_locus(an_ifc_module                        *mod,
                               const an_ifc_form_identifier_storage *universal)
/*
Return TRUE if the given universal representation storage from the given module
has the field "locus"; otherwise, return FALSE.
*/
{
  a_boolean result = get_fallback_presence_value(mod);

  if (is_at_least(mod, 0, 33)) {
    result = TRUE;
  }  /* if */
  return result;
}  /* has_ifc_locus */


inline a_boolean has_ifc_locus(const an_ifc_form_identifier &universal)
/*
Return TRUE if the given universal representation has the field "locus";
otherwise, return FALSE.
*/
{
  return has_ifc_locus(universal.get_module(), universal.get_storage());
}  /* has_ifc_locus */


inline an_ifc_source_location get_ifc_locus(
                               an_ifc_module                        *mod,
                               const an_ifc_form_identifier_storage *universal)
/*
Given the universal storage representation of FormIdentifier and the associated
module, return the universal representation of the field "locus".
*/
{
  an_ifc_source_location result;

  /* Ensure the locus field exists in the current module version. */
  check_assertion(has_ifc_locus(mod, universal));
  an_ifc_source_location_bytes stage_0;
  an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
  /* Update the universal storage pointer to the start of the field
     (FormIdentifier::locus - SourceLocation). */
  stage_0 = (an_ifc_source_location_bytes)((*universal) + 0);
#else /* !USE_MMAP_FOR_MODULES */
  /* Copy the field (FormIdentifier::locus - SourceLocation) into universal
     storage. */
  copy_ifc_field(&stage_0, universal, /*offset=*/0, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
  stage_1 = {mod, stage_0};
  result = stage_1;
  return result;
}  /* get_ifc_locus */


inline an_ifc_source_location get_ifc_locus(
                                       const an_ifc_form_identifier &universal)
/*
Given the universal representation of FormIdentifier, return the universal
representation of the field "locus".
*/
{
  return get_ifc_locus(universal.get_module(), universal.get_storage());
}  /* get_ifc_locus */


inline a_boolean has_ifc_spelling(
                               an_ifc_module                        *mod,
                               const an_ifc_form_identifier_storage *universal)
/*
Return TRUE if the given universal representation storage from the given module
has the field "spelling"; otherwise, return FALSE.
*/
{
  a_boolean result = get_fallback_presence_value(mod);

  if (is_at_least(mod, 0, 33)) {
    result = TRUE;
  }  /* if */
  return result;
}  /* has_ifc_spelling */


inline a_boolean has_ifc_spelling(const an_ifc_form_identifier &universal)
/*
Return TRUE if the given universal representation has the field "spelling";
otherwise, return FALSE.
*/
{
  return has_ifc_spelling(universal.get_module(), universal.get_storage());
}  /* has_ifc_spelling */


inline an_ifc_text_offset get_ifc_spelling(
                               an_ifc_module                        *mod,
                               const an_ifc_form_identifier_storage *universal)
/*
Given the universal storage representation of FormIdentifier and the associated
module, return the universal representation of the field "spelling".
*/
{
  an_ifc_text_offset result;

  /* Ensure the spelling field exists in the current module version. */
  check_assertion(has_ifc_spelling(mod, universal));
  /* Copy the contents to an appropriately sized variable.  Then, copy via
     language rules into a (possibly wider) native type.  This is irrelevant
     (and should be optimized away) on little-endian architectures.  However,
     when running on big-endian architectures this process ensures the value
     isn't mangled (as with high order bits first, a wider integer increases
     the value if the bits aren't positioned properly). */
  an_ifc_text_offset_0_33 stage_0;
  an_ifc_text_offset      stage_1;

  /* Copy the field (FormIdentifier::spelling - TextOffset) into version
     specific storage. */
  static_assert(sizeof(stage_0) == 4,
                "stage_0 is not properly sized storage!");
  copy_ifc_field(&stage_0, universal, /*offset=*/8);
  stage_1 = {mod, (an_ifc_text_offset_storage)stage_0};
  result = stage_1;
  return result;
}  /* get_ifc_spelling */


inline an_ifc_text_offset get_ifc_spelling(
                                       const an_ifc_form_identifier &universal)
/*
Given the universal representation of FormIdentifier, return the universal
representation of the field "spelling".
*/
{
  return get_ifc_spelling(universal.get_module(), universal.get_storage());
}  /* get_ifc_spelling */


