inline a_boolean validate(an_ifc_module                            *mod,
                          const an_ifc_macro_function_like_storage *universal,
                          const an_ifc_validation_trace            *parent)
/*
Given the universal storage representation of MacroFunctionLike and the
associated module, return TRUE if the representation is valid; otherwise,
return FALSE.
*/
{
  a_boolean result = TRUE;

  if (has_ifc_body(mod, universal)) {
    an_ifc_form_index_0_33  stage_0;
    an_ifc_validation_trace stage_0_trace = {"body", /*offset=*/16, parent};

    /* Copy the field (MacroFunctionLike::body - FormIndex) into version
       specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/16);
    if (!validate_index(mod, stage_0, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_locus(mod, universal)) {
    an_ifc_source_location_bytes stage_0;
    an_ifc_validation_trace      stage_0_trace =
                                               {"locus", /*offset=*/0, parent};
    an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (MacroFunctionLike::locus - SourceLocation). */
    stage_0 = (an_ifc_source_location_bytes)((*universal) + 0);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (MacroFunctionLike::locus - SourceLocation) into
       universal storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/0, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_parameters(mod, universal)) {
    an_ifc_form_index_0_33  stage_0;
    an_ifc_validation_trace stage_0_trace =
                                         {"parameters", /*offset=*/12, parent};

    /* Copy the field (MacroFunctionLike::parameters - FormIndex) into version
       specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/12);
    if (!validate_index(mod, stage_0, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
done:
  return result;
}  /* validate */


inline a_boolean validate(const an_ifc_macro_function_like &universal,
                          const an_ifc_validation_trace    *parent)
/*
Given the universal representation of MacroFunctionLike, return TRUE if the
representation is valid; otherwise, return FALSE.
*/
{
  return validate(universal.get_module(), universal.get_storage(), parent);
}  /* validate */


