inline a_boolean validate(
                       an_ifc_module                                *mod,
                       const an_ifc_module_import_reference_storage *universal,
                       const an_ifc_validation_trace                *parent)
/*
Given the universal storage representation of ModuleImportReference and the
associated module, return TRUE if the representation is valid; otherwise,
return FALSE.
*/
{
  a_boolean result = TRUE;

  if (has_ifc_reference(mod, universal)) {
    an_ifc_module_reference_bytes stage_0;
    an_ifc_validation_trace       stage_0_trace =
                                           {"reference", /*offset=*/0, parent};
    an_ifc_module_reference       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (ModuleImportReference::reference - ModuleReference). */
    stage_0 = (an_ifc_module_reference_bytes)((*universal) + 0);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (ModuleImportReference::reference - ModuleReference) into
       universal storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/0, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
done:
  return result;
}  /* validate */


