inline a_boolean validate(an_ifc_module                      *mod,
                          const an_ifc_name_operator_storage *universal,
                          const an_ifc_validation_trace      *parent)
/*
Given the universal storage representation of NameOperator and the associated
module, return TRUE if the representation is valid; otherwise, return FALSE.
*/
{
  a_boolean result = TRUE;

  if (has_ifc_operator(mod, universal)) {
    an_ifc_operator_category_0_33 stage_0;
    an_ifc_validation_trace       stage_0_trace =
                                            {"operator", /*offset=*/4, parent};

    /* Copy the field (NameOperator::operator - OperatorCategory) into version
       specific storage. */
    static_assert(sizeof(stage_0) == 2,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/4);
    if (!validate_category(mod, stage_0, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
done:
  return result;
}  /* validate */


