inline an_ifc_decl_index get_ifc_index(
                                  an_ifc_module                     *mod,
                                  const an_ifc_scope_member_storage *universal)
/*
Given the universal storage representation of ScopeMember and the associated
module, return the universal representation of the field "index".
*/
{
  an_ifc_decl_index result;

  /* Ensure the index field exists in the current module version. */
  check_assertion(has_ifc_index(mod, universal));
  if (is_at_least(mod, 0, 41)) {
    an_ifc_decl_index_0_41 stage_0;
    an_ifc_decl_index      stage_1;

    /* Copy the field (ScopeMember::index - DeclIndex) into version specific
       storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/0);
    stage_1 = to_universal_index(mod, stage_0);
    result = stage_1;
  } else {
    an_ifc_decl_index_0_33 stage_0;
    an_ifc_decl_index      stage_1;

    /* Copy the field (ScopeMember::index - DeclIndex) into version specific
       storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/0);
    stage_1 = to_universal_index(mod, stage_0);
    result = stage_1;
  }  /* if */
  return result;
}  /* get_ifc_index */


inline an_ifc_decl_index get_ifc_index(const an_ifc_scope_member &universal)
/*
Given the universal representation of ScopeMember, return the universal
representation of the field "index".
*/
{
  return get_ifc_index(universal.get_module(), universal.get_storage());
}  /* get_ifc_index */


inline a_boolean validate(an_ifc_module                     *mod,
                          const an_ifc_scope_member_storage *universal,
                          const an_ifc_validation_trace     *parent)
/*
Given the universal storage representation of ScopeMember and the associated
module, return TRUE if the representation is valid; otherwise, return FALSE.
*/
{
  a_boolean result = TRUE;

  if (has_ifc_index(mod, universal)) {
    if (is_at_least(mod, 0, 41)) {
      an_ifc_decl_index_0_41  stage_0;
      an_ifc_validation_trace stage_0_trace = {"index", /*offset=*/0, parent};

      /* Copy the field (ScopeMember::index - DeclIndex) into version specific
         storage. */
      static_assert(sizeof(stage_0) == 4,
                    "stage_0 is not properly sized storage!");
      copy_ifc_field(&stage_0, universal, /*offset=*/0);
      if (!validate_index(mod, stage_0, &stage_0_trace)) {
        result = FALSE;
        goto done;
      }  /* if */
    } else {
      an_ifc_decl_index_0_33  stage_0;
      an_ifc_validation_trace stage_0_trace = {"index", /*offset=*/0, parent};

      /* Copy the field (ScopeMember::index - DeclIndex) into version specific
         storage. */
      static_assert(sizeof(stage_0) == 4,
                    "stage_0 is not properly sized storage!");
      copy_ifc_field(&stage_0, universal, /*offset=*/0);
      if (!validate_index(mod, stage_0, &stage_0_trace)) {
        result = FALSE;
        goto done;
      }  /* if */
    }  /* if */
  }  /* if */
done:
  return result;
}  /* validate */


inline a_boolean validate(const an_ifc_scope_member     &universal,
                          const an_ifc_validation_trace *parent)
/*
Given the universal representation of ScopeMember, return TRUE if the
representation is valid; otherwise, return FALSE.
*/
{
  return validate(universal.get_module(), universal.get_storage(), parent);
}  /* validate */


