inline an_ifc_decl_index get_ifc_decl(
                            an_ifc_module                           *mod,
                            const an_ifc_stmt_variable_decl_storage *universal)
/*
Given the universal storage representation of StmtVariableDecl and the
associated module, return the universal representation of the field "decl".
*/
{
  an_ifc_decl_index result;

  /* Ensure the decl field exists in the current module version. */
  check_assertion(has_ifc_decl(mod, universal));
  if (is_at_least(mod, 0, 41)) {
    an_ifc_decl_index_0_41 stage_0;
    an_ifc_decl_index      stage_1;

    /* Copy the field (StmtVariableDecl::decl - DeclIndex) into version
       specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/0);
    stage_1 = to_universal_index(mod, stage_0);
    result = stage_1;
  } else {
    an_ifc_decl_index_0_33 stage_0;
    an_ifc_decl_index      stage_1;

    /* Copy the field (StmtVariableDecl::decl - DeclIndex) into version
       specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/0);
    stage_1 = to_universal_index(mod, stage_0);
    result = stage_1;
  }  /* if */
  return result;
}  /* get_ifc_decl */


