inline a_boolean has_ifc_aliasee(
                      an_ifc_module                                 *mod,
                      const an_ifc_syntax_alias_declaration_storage *universal)
/*
Return TRUE if the given universal representation storage from the given module
has the field "aliasee"; otherwise, return FALSE.
*/
{
  a_boolean result = get_fallback_presence_value(mod);

  if (is_at_least(mod, 0, 33)) {
    result = TRUE;
  }  /* if */
  return result;
}  /* has_ifc_aliasee */


inline a_boolean has_ifc_aliasee(
                              const an_ifc_syntax_alias_declaration &universal)
/*
Return TRUE if the given universal representation has the field "aliasee";
otherwise, return FALSE.
*/
{
  return has_ifc_aliasee(universal.get_module(), universal.get_storage());
}  /* has_ifc_aliasee */


inline an_ifc_syntax_index get_ifc_aliasee(
                      an_ifc_module                                 *mod,
                      const an_ifc_syntax_alias_declaration_storage *universal)
/*
Given the universal storage representation of SyntaxAliasDeclaration and the
associated module, return the universal representation of the field "aliasee".
*/
{
  an_ifc_syntax_index result;

  /* Ensure the aliasee field exists in the current module version. */
  check_assertion(has_ifc_aliasee(mod, universal));
  an_ifc_syntax_index_0_33 stage_0;
  an_ifc_syntax_index      stage_1;

  /* Copy the field (SyntaxAliasDeclaration::aliasee - SyntaxIndex) into
     version specific storage. */
  static_assert(sizeof(stage_0) == 4,
                "stage_0 is not properly sized storage!");
  copy_ifc_field(&stage_0, universal, /*offset=*/4);
  stage_1 = to_universal_index(mod, stage_0);
  result = stage_1;
  return result;
}  /* get_ifc_aliasee */


inline an_ifc_syntax_index get_ifc_aliasee(
                              const an_ifc_syntax_alias_declaration &universal)
/*
Given the universal representation of SyntaxAliasDeclaration, return the
universal representation of the field "aliasee".
*/
{
  return get_ifc_aliasee(universal.get_module(), universal.get_storage());
}  /* get_ifc_aliasee */


