inline a_boolean has_ifc_left_paren(
                                an_ifc_module                       *mod,
                                const an_ifc_syntax_alignas_storage *universal)
/*
Return TRUE if the given universal representation storage from the given module
has the field "left_paren"; otherwise, return FALSE.
*/
{
  a_boolean result = get_fallback_presence_value(mod);

  if (is_at_least(mod, 0, 33)) {
    result = TRUE;
  }  /* if */
  return result;
}  /* has_ifc_left_paren */


