inline a_boolean validate(an_ifc_module                       *mod,
                          const an_ifc_syntax_alignas_storage *universal,
                          const an_ifc_validation_trace       *parent)
/*
Given the universal storage representation of SyntaxAlignas and the associated
module, return TRUE if the representation is valid; otherwise, return FALSE.
*/
{
  a_boolean result = TRUE;

  if (has_ifc_left_paren(mod, universal)) {
    an_ifc_source_location_bytes stage_0;
    an_ifc_validation_trace      stage_0_trace =
                                         {"left_paren", /*offset=*/12, parent};
    an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (SyntaxAlignas::left_paren - SourceLocation). */
    stage_0 = (an_ifc_source_location_bytes)((*universal) + 12);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (SyntaxAlignas::left_paren - SourceLocation) into
       universal storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/12, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_locus(mod, universal)) {
    an_ifc_source_location_bytes stage_0;
    an_ifc_validation_trace      stage_0_trace =
                                               {"locus", /*offset=*/4, parent};
    an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (SyntaxAlignas::locus - SourceLocation). */
    stage_0 = (an_ifc_source_location_bytes)((*universal) + 4);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (SyntaxAlignas::locus - SourceLocation) into universal
       storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/4, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_operand(mod, universal)) {
    an_ifc_syntax_index_0_33 stage_0;
    an_ifc_validation_trace  stage_0_trace = {"operand", /*offset=*/0, parent};

    /* Copy the field (SyntaxAlignas::operand - SyntaxIndex) into version
       specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/0);
    if (!validate_index(mod, stage_0, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_right_paren(mod, universal)) {
    an_ifc_source_location_bytes stage_0;
    an_ifc_validation_trace      stage_0_trace =
                                        {"right_paren", /*offset=*/20, parent};
    an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (SyntaxAlignas::right_paren - SourceLocation). */
    stage_0 = (an_ifc_source_location_bytes)((*universal) + 20);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (SyntaxAlignas::right_paren - SourceLocation) into
       universal storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/20, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
done:
  return result;
}  /* validate */


inline a_boolean validate(const an_ifc_syntax_alignas   &universal,
                          const an_ifc_validation_trace *parent)
/*
Given the universal representation of SyntaxAlignas, return TRUE if the
representation is valid; otherwise, return FALSE.
*/
{
  return validate(universal.get_module(), universal.get_storage(), parent);
}  /* validate */


