inline an_ifc_syntax_index get_ifc_declarator(
           an_ifc_module                                            *mod,
           const an_ifc_syntax_array_or_function_declarator_storage *universal)
/*
Given the universal storage representation of SyntaxArrayOrFunctionDeclarator
and the associated module, return the universal representation of the field
"declarator".
*/
{
  an_ifc_syntax_index result;

  /* Ensure the declarator field exists in the current module version. */
  check_assertion(has_ifc_declarator(mod, universal));
  an_ifc_syntax_index_0_33 stage_0;
  an_ifc_syntax_index      stage_1;

  /* Copy the field (SyntaxArrayOrFunctionDeclarator::declarator - SyntaxIndex)
     into version specific storage. */
  static_assert(sizeof(stage_0) == 4,
                "stage_0 is not properly sized storage!");
  copy_ifc_field(&stage_0, universal, /*offset=*/0);
  stage_1 = to_universal_index(mod, stage_0);
  result = stage_1;
  return result;
}  /* get_ifc_declarator */


