inline an_ifc_source_location get_ifc_left_paren(
              an_ifc_module                                         *mod,
              const an_ifc_syntax_attribute_argument_clause_storage *universal)
/*
Given the universal storage representation of SyntaxAttributeArgumentClause and
the associated module, return the universal representation of the field
"left_paren".
*/
{
  an_ifc_source_location result;

  /* Ensure the left_paren field exists in the current module version. */
  check_assertion(has_ifc_left_paren(mod, universal));
  an_ifc_source_location_bytes stage_0;
  an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
  /* Update the universal storage pointer to the start of the field
     (SyntaxAttributeArgumentClause::left_paren - SourceLocation). */
  stage_0 = (an_ifc_source_location_bytes)((*universal) + 4);
#else /* !USE_MMAP_FOR_MODULES */
  /* Copy the field (SyntaxAttributeArgumentClause::left_paren -
     SourceLocation) into universal storage. */
  copy_ifc_field(&stage_0, universal, /*offset=*/4, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
  stage_1 = {mod, stage_0};
  result = stage_1;
  return result;
}  /* get_ifc_left_paren */


