inline a_boolean validate(
                        an_ifc_module                               *mod,
                        const an_ifc_syntax_break_statement_storage *universal,
                        const an_ifc_validation_trace               *parent)
/*
Given the universal storage representation of SyntaxBreakStatement and the
associated module, return TRUE if the representation is valid; otherwise,
return FALSE.
*/
{
  a_boolean result = TRUE;

  if (has_ifc_break(mod, universal)) {
    an_ifc_source_location_bytes stage_0;
    an_ifc_validation_trace      stage_0_trace =
                                               {"break", /*offset=*/0, parent};
    an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (SyntaxBreakStatement::break - SourceLocation). */
    stage_0 = (an_ifc_source_location_bytes)((*universal) + 0);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (SyntaxBreakStatement::break - SourceLocation) into
       universal storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/0, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_semicolon(mod, universal)) {
    an_ifc_source_location_bytes stage_0;
    an_ifc_validation_trace      stage_0_trace =
                                           {"semicolon", /*offset=*/8, parent};
    an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (SyntaxBreakStatement::semicolon - SourceLocation). */
    stage_0 = (an_ifc_source_location_bytes)((*universal) + 8);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (SyntaxBreakStatement::semicolon - SourceLocation) into
       universal storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/8, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
done:
  return result;
}  /* validate */


inline a_boolean validate(const an_ifc_syntax_break_statement &universal,
                          const an_ifc_validation_trace       *parent)
/*
Given the universal representation of SyntaxBreakStatement, return TRUE if the
representation is valid; otherwise, return FALSE.
*/
{
  return validate(universal.get_module(), universal.get_storage(), parent);
}  /* validate */


