inline an_ifc_source_location get_ifc_left_curly(
                     an_ifc_module                                  *mod,
                     const an_ifc_syntax_compound_statement_storage *universal)
/*
Given the universal storage representation of SyntaxCompoundStatement and the
associated module, return the universal representation of the field
"left_curly".
*/
{
  an_ifc_source_location result;

  /* Ensure the left_curly field exists in the current module version. */
  check_assertion(has_ifc_left_curly(mod, universal));
  an_ifc_source_location_bytes stage_0;
  an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
  /* Update the universal storage pointer to the start of the field
     (SyntaxCompoundStatement::left_curly - SourceLocation). */
  stage_0 = (an_ifc_source_location_bytes)((*universal) + 8);
#else /* !USE_MMAP_FOR_MODULES */
  /* Copy the field (SyntaxCompoundStatement::left_curly - SourceLocation) into
     universal storage. */
  copy_ifc_field(&stage_0, universal, /*offset=*/8, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
  stage_1 = {mod, stage_0};
  result = stage_1;
  return result;
}  /* get_ifc_left_curly */


