inline a_boolean validate(
                     an_ifc_module                                  *mod,
                     const an_ifc_syntax_concept_definition_storage *universal,
                     const an_ifc_validation_trace                  *parent)
/*
Given the universal storage representation of SyntaxConceptDefinition and the
associated module, return TRUE if the representation is valid; otherwise,
return FALSE.
*/
{
  a_boolean result = TRUE;

  if (has_ifc_concept_keyword(mod, universal)) {
    an_ifc_source_location_bytes stage_0;
    an_ifc_validation_trace      stage_0_trace =
                                    {"concept_keyword", /*offset=*/20, parent};
    an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (SyntaxConceptDefinition::concept_keyword - SourceLocation). */
    stage_0 = (an_ifc_source_location_bytes)((*universal) + 20);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (SyntaxConceptDefinition::concept_keyword -
       SourceLocation) into universal storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/20, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_equal(mod, universal)) {
    an_ifc_source_location_bytes stage_0;
    an_ifc_validation_trace      stage_0_trace =
                                              {"equal", /*offset=*/28, parent};
    an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (SyntaxConceptDefinition::equal - SourceLocation). */
    stage_0 = (an_ifc_source_location_bytes)((*universal) + 28);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (SyntaxConceptDefinition::equal - SourceLocation) into
       universal storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/28, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_initializer(mod, universal)) {
    an_ifc_expr_index_0_33  stage_0;
    an_ifc_validation_trace stage_0_trace =
                                        {"initializer", /*offset=*/16, parent};

    /* Copy the field (SyntaxConceptDefinition::initializer - ExprIndex) into
       version specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/16);
    if (!validate_index(mod, stage_0, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_locus(mod, universal)) {
    an_ifc_source_location_bytes stage_0;
    an_ifc_validation_trace      stage_0_trace =
                                               {"locus", /*offset=*/4, parent};
    an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (SyntaxConceptDefinition::locus - SourceLocation). */
    stage_0 = (an_ifc_source_location_bytes)((*universal) + 4);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (SyntaxConceptDefinition::locus - SourceLocation) into
       universal storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/4, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_parameters(mod, universal)) {
    an_ifc_syntax_index_0_33 stage_0;
    an_ifc_validation_trace  stage_0_trace =
                                          {"parameters", /*offset=*/0, parent};

    /* Copy the field (SyntaxConceptDefinition::parameters - SyntaxIndex) into
       version specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/0);
    if (!validate_index(mod, stage_0, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_semicolon(mod, universal)) {
    an_ifc_source_location_bytes stage_0;
    an_ifc_validation_trace      stage_0_trace =
                                          {"semicolon", /*offset=*/36, parent};
    an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (SyntaxConceptDefinition::semicolon - SourceLocation). */
    stage_0 = (an_ifc_source_location_bytes)((*universal) + 36);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (SyntaxConceptDefinition::semicolon - SourceLocation)
       into universal storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/36, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
done:
  return result;
}  /* validate */


