{
  return has_ifc_decl_specifier(universal.get_module(),
                                universal.get_storage());
}  /* has_ifc_decl_specifier */


inline an_ifc_syntax_index get_ifc_decl_specifier(
                  an_ifc_module                                     *mod,
                  const an_ifc_syntax_condition_declaration_storage *universal)
/*
Given the universal storage representation of SyntaxConditionDeclaration and
the associated module, return the universal representation of the field
"decl_specifier".
*/
{
  an_ifc_syntax_index result;

  /* Ensure the decl_specifier field exists in the current module version. */
  check_assertion(has_ifc_decl_specifier(mod, universal));
  an_ifc_syntax_index_0_33 stage_0;
  an_ifc_syntax_index      stage_1;

  /* Copy the field (SyntaxConditionDeclaration::decl_specifier - SyntaxIndex)
     into version specific storage. */
  static_assert(sizeof(stage_0) == 4,
                "stage_0 is not properly sized storage!");
  copy_ifc_field(&stage_0, universal, /*offset=*/0);
  stage_1 = to_universal_index(mod, stage_0);
  result = stage_1;
  return result;
}  /* get_ifc_decl_specifier */


