inline a_boolean validate(
                  an_ifc_module                                     *mod,
                  const an_ifc_syntax_enumerator_definition_storage *universal,
                  const an_ifc_validation_trace                     *parent)
/*
Given the universal storage representation of SyntaxEnumeratorDefinition and
the associated module, return TRUE if the representation is valid; otherwise,
return FALSE.
*/
{
  a_boolean result = TRUE;

  if (has_ifc_comma(mod, universal)) {
    an_ifc_source_location_bytes stage_0;
    an_ifc_validation_trace      stage_0_trace =
                                              {"comma", /*offset=*/24, parent};
    an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (SyntaxEnumeratorDefinition::comma - SourceLocation). */
    stage_0 = (an_ifc_source_location_bytes)((*universal) + 24);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (SyntaxEnumeratorDefinition::comma - SourceLocation) into
       universal storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/24, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_equal(mod, universal)) {
    an_ifc_source_location_bytes stage_0;
    an_ifc_validation_trace      stage_0_trace =
                                              {"equal", /*offset=*/16, parent};
    an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (SyntaxEnumeratorDefinition::equal - SourceLocation). */
    stage_0 = (an_ifc_source_location_bytes)((*universal) + 16);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (SyntaxEnumeratorDefinition::equal - SourceLocation) into
       universal storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/16, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_initializer(mod, universal)) {
    an_ifc_expr_index_0_33  stage_0;
    an_ifc_validation_trace stage_0_trace =
                                         {"initializer", /*offset=*/4, parent};

    /* Copy the field (SyntaxEnumeratorDefinition::initializer - ExprIndex)
       into version specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/4);
    if (!validate_index(mod, stage_0, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_locus(mod, universal)) {
    an_ifc_source_location_bytes stage_0;
    an_ifc_validation_trace      stage_0_trace =
                                               {"locus", /*offset=*/8, parent};
    an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (SyntaxEnumeratorDefinition::locus - SourceLocation). */
    stage_0 = (an_ifc_source_location_bytes)((*universal) + 8);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (SyntaxEnumeratorDefinition::locus - SourceLocation) into
       universal storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/8, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
done:
  return result;
}  /* validate */


inline a_boolean validate(const an_ifc_syntax_enumerator_definition &universal,
                          const an_ifc_validation_trace             *parent)
/*
Given the universal representation of SyntaxEnumeratorDefinition, return TRUE
if the representation is valid; otherwise, return FALSE.
*/
{
  return validate(universal.get_module(), universal.get_storage(), parent);
}  /* validate */


