inline an_ifc_syntax_index get_ifc_init(
                         an_ifc_module                              *mod,
                         const an_ifc_syntax_init_statement_storage *universal)
/*
Given the universal storage representation of SyntaxInitStatement and the
associated module, return the universal representation of the field "init".
*/
{
  an_ifc_syntax_index result;

  /* Ensure the init field exists in the current module version. */
  check_assertion(has_ifc_init(mod, universal));
  an_ifc_syntax_index_0_33 stage_0;
  an_ifc_syntax_index      stage_1;

  /* Copy the field (SyntaxInitStatement::init - SyntaxIndex) into version
     specific storage. */
  static_assert(sizeof(stage_0) == 4,
                "stage_0 is not properly sized storage!");
  copy_ifc_field(&stage_0, universal, /*offset=*/4);
  stage_1 = to_universal_index(mod, stage_0);
  result = stage_1;
  return result;
}  /* get_ifc_init */


