inline a_boolean validate(
                       an_ifc_module                                *mod,
                       const an_ifc_syntax_using_declarator_storage *universal,
                       const an_ifc_validation_trace                *parent)
/*
Given the universal storage representation of SyntaxUsingDeclarator and the
associated module, return TRUE if the representation is valid; otherwise,
return FALSE.
*/
{
  a_boolean result = TRUE;

  if (has_ifc_comma(mod, universal)) {
    an_ifc_source_location_bytes stage_0;
    an_ifc_validation_trace      stage_0_trace =
                                              {"comma", /*offset=*/20, parent};
    an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (SyntaxUsingDeclarator::comma - SourceLocation). */
    stage_0 = (an_ifc_source_location_bytes)((*universal) + 20);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (SyntaxUsingDeclarator::comma - SourceLocation) into
       universal storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/20, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_expander(mod, universal)) {
    an_ifc_source_location_bytes stage_0;
    an_ifc_validation_trace      stage_0_trace =
                                           {"expander", /*offset=*/12, parent};
    an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (SyntaxUsingDeclarator::expander - SourceLocation). */
    stage_0 = (an_ifc_source_location_bytes)((*universal) + 12);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (SyntaxUsingDeclarator::expander - SourceLocation) into
       universal storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/12, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_qualified_name(mod, universal)) {
    an_ifc_expr_index_0_33  stage_0;
    an_ifc_validation_trace stage_0_trace =
                                      {"qualified_name", /*offset=*/0, parent};

    /* Copy the field (SyntaxUsingDeclarator::qualified_name - ExprIndex) into
       version specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/0);
    if (!validate_index(mod, stage_0, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
  if (has_ifc_typename_kw(mod, universal)) {
    an_ifc_source_location_bytes stage_0;
    an_ifc_validation_trace      stage_0_trace =
                                         {"typename_kw", /*offset=*/4, parent};
    an_ifc_source_location       stage_1;

#if USE_MMAP_FOR_MODULES
    /* Update the universal storage pointer to the start of the field
       (SyntaxUsingDeclarator::typename_kw - SourceLocation). */
    stage_0 = (an_ifc_source_location_bytes)((*universal) + 4);
#else /* !USE_MMAP_FOR_MODULES */
    /* Copy the field (SyntaxUsingDeclarator::typename_kw - SourceLocation)
       into universal storage. */
    copy_ifc_field(&stage_0, universal, /*offset=*/4, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
    stage_1 = {mod, stage_0};
    if (!validate(stage_1, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
done:
  return result;
}  /* validate */


