inline a_boolean validate(an_ifc_module                             *mod,
                          const an_ifc_trait_alias_template_storage *universal,
                          const an_ifc_validation_trace             *parent)
/*
Given the universal storage representation of TraitAliasTemplate and the
associated module, return TRUE if the representation is valid; otherwise,
return FALSE.
*/
{
  a_boolean result = TRUE;

  if (has_ifc_decl(mod, universal)) {
    if (is_at_least(mod, 0, 41)) {
      an_ifc_decl_index_0_41  stage_0;
      an_ifc_validation_trace stage_0_trace = {"decl", /*offset=*/0, parent};

      /* Copy the field (TraitAliasTemplate::decl - DeclIndex) into version
         specific storage. */
      static_assert(sizeof(stage_0) == 4,
                    "stage_0 is not properly sized storage!");
      copy_ifc_field(&stage_0, universal, /*offset=*/0);
      if (!validate_index(mod, stage_0, &stage_0_trace)) {
        result = FALSE;
        goto done;
      }  /* if */
    } else {
      an_ifc_decl_index_0_33  stage_0;
      an_ifc_validation_trace stage_0_trace = {"decl", /*offset=*/0, parent};

      /* Copy the field (TraitAliasTemplate::decl - DeclIndex) into version
         specific storage. */
      static_assert(sizeof(stage_0) == 4,
                    "stage_0 is not properly sized storage!");
      copy_ifc_field(&stage_0, universal, /*offset=*/0);
      if (!validate_index(mod, stage_0, &stage_0_trace)) {
        result = FALSE;
        goto done;
      }  /* if */
    }  /* if */
  }  /* if */
  if (has_ifc_trait(mod, universal)) {
    an_ifc_syntax_index_0_33 stage_0;
    an_ifc_validation_trace  stage_0_trace = {"trait", /*offset=*/4, parent};

    /* Copy the field (TraitAliasTemplate::trait - SyntaxIndex) into version
       specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/4);
    if (!validate_index(mod, stage_0, &stage_0_trace)) {
      result = FALSE;
      goto done;
    }  /* if */
  }  /* if */
done:
  return result;
}  /* validate */


inline a_boolean validate(const an_ifc_trait_alias_template &universal,
                          const an_ifc_validation_trace     *parent)
/*
Given the universal representation of TraitAliasTemplate, return TRUE if the
representation is valid; otherwise, return FALSE.
*/
{
  return validate(universal.get_module(), universal.get_storage(), parent);
}  /* validate */


