inline an_ifc_sequence get_ifc_trait(
                                  an_ifc_module                     *mod,
                                  const an_ifc_trait_friend_storage *universal)
/*
Given the universal storage representation of TraitFriend and the associated
module, return the universal representation of the field "trait".
*/
{
  an_ifc_sequence result;

  /* Ensure the trait field exists in the current module version. */
  check_assertion(has_ifc_trait(mod, universal));
  an_ifc_sequence_bytes stage_0;
  an_ifc_sequence       stage_1;

#if USE_MMAP_FOR_MODULES
  /* Update the universal storage pointer to the start of the field
     (TraitFriend::trait - Sequence). */
  stage_0 = (an_ifc_sequence_bytes)((*universal) + 4);
#else /* !USE_MMAP_FOR_MODULES */
  /* Copy the field (TraitFriend::trait - Sequence) into universal storage. */
  copy_ifc_field(&stage_0, universal, /*offset=*/4, /*size=*/8);
#endif /* USE_MMAP_FOR_MODULES */
  stage_1 = {mod, stage_0};
  result = stage_1;
  return result;
}  /* get_ifc_trait */


