inline an_ifc_encoded_decl_index get_ifc_encoded_decl(
                          an_ifc_module                             *mod,
                          const an_ifc_trait_specialization_storage *universal)
/*
Given the universal storage representation of TraitSpecialization and the
associated module, return the universal representation of the field
"encoded_decl".
*/
{
  an_ifc_encoded_decl_index result;

  /* Ensure the encoded_decl field exists in the current module version. */
  check_assertion(has_ifc_encoded_decl(mod, universal));
  /* Copy the contents to an appropriately sized variable.  Then, copy via
     language rules into a (possibly wider) native type.  This is irrelevant
     (and should be optimized away) on little-endian architectures.  However,
     when running on big-endian architectures this process ensures the value
     isn't mangled (as with high order bits first, a wider integer increases
     the value if the bits aren't positioned properly). */
  if (is_at_least(mod, 0, 41)) {
    an_ifc_decl_index_0_41    stage_0;
    an_ifc_decl_index         stage_1;
    an_ifc_encoded_decl_index stage_2;

    /* Copy the field (TraitSpecialization::decl - DeclIndex) into version
       specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/0);
    stage_1 = to_universal_index(mod, stage_0);
    /* Use the encoding matching the request, regardless of where we're coming
       from, to get an encoding result that matches the source node (and is
       thus, arguably the least surprising). */
    stage_2 = to_encoded(mod, stage_1);
    result = stage_2;
  } else {
    an_ifc_decl_index_0_33    stage_0;
    an_ifc_decl_index         stage_1;
    an_ifc_encoded_decl_index stage_2;

    /* Copy the field (TraitSpecialization::decl - DeclIndex) into version
       specific storage. */
    static_assert(sizeof(stage_0) == 4,
                  "stage_0 is not properly sized storage!");
    copy_ifc_field(&stage_0, universal, /*offset=*/0);
    stage_1 = to_universal_index(mod, stage_0);
    /* Use the encoding matching the request, regardless of where we're coming
       from, to get an encoding result that matches the source node (and is
       thus, arguably the least surprising). */
    stage_2 = to_encoded(mod, stage_1);
    result = stage_2;
  }  /* if */
  return result;
}  /* get_ifc_encoded_decl */


