inline an_ifc_bool get_ifc_pack_expanded(
                                     an_ifc_module                  *mod,
                                     const an_ifc_type_base_storage *universal)
/*
Given the universal storage representation of TypeBase and the associated
module, return the universal representation of the field "pack_expanded".
*/
{
  an_ifc_bool result;

  /* Ensure the pack_expanded field exists in the current module version. */
  check_assertion(has_ifc_pack_expanded(mod, universal));
  /* Copy the contents to an appropriately sized variable.  Then, copy via
     language rules into a (possibly wider) native type.  This is irrelevant
     (and should be optimized away) on little-endian architectures.  However,
     when running on big-endian architectures this process ensures the value
     isn't mangled (as with high order bits first, a wider integer increases
     the value if the bits aren't positioned properly). */
  an_ifc_bool_0_33 stage_0;
  an_ifc_bool      stage_1;

  /* Copy the field (TypeBase::pack_expanded - bool) into version specific
     storage. */
  static_assert(sizeof(stage_0) == 1,
                "stage_0 is not properly sized storage!");
  copy_ifc_field(&stage_0, universal, /*offset=*/6);
  stage_1 = {mod, (an_ifc_bool_storage)stage_0};
  result = stage_1;
  return result;
}  /* get_ifc_pack_expanded */


