    case ifc_ds_decl_destructor:
      if (is_at_least(mod, 0, 33)) {
        result = TRUE;
      }  /* if */
      break;
    case ifc_ds_decl_enumeration:
      if (is_at_least(mod, 0, 33)) {
        result = TRUE;
      }  /* if */
      break;
    case ifc_ds_decl_enumerator:
      if (is_at_least(mod, 0, 33)) {
        result = TRUE;
      }  /* if */
      break;
    case ifc_ds_decl_field:
