    case ifc_ds_decl_inherited_constructor:
      if (is_at_least(mod, 0, 33)) {
        result = TRUE;
      }  /* if */
      break;
    case ifc_ds_decl_intrinsic:
      if (is_at_least(mod, 0, 33)) {
        result = TRUE;
      }  /* if */
      break;
    case ifc_ds_decl_method:
      if (is_at_least(mod, 0, 33)) {
        result = TRUE;
      }  /* if */
      break;
    case ifc_ds_decl_partial_specialization:
      if (is_at_least(mod, 0, 33)) {
        result = TRUE;
      }  /* if */
      break;
    case ifc_ds_decl_scope:
